-- Guarded each ALTER POLICY to run only where the policy exists (production created it outside migrations); production applied the original text.
-- Audio catalog files are generated by the service-role meditation endpoint.
-- Public bucket downloads remain available; anonymous/client writes are not required.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname = 'storage'
      AND tablename = 'objects' AND policyname = 'Service role can upload audio files') THEN
    ALTER POLICY "Service role can upload audio files" ON storage.objects TO service_role;
  END IF;
END
$$;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname = 'storage'
      AND tablename = 'objects' AND policyname = 'Service role can update audio files') THEN
    ALTER POLICY "Service role can update audio files" ON storage.objects TO service_role;
  END IF;
END
$$;
